import numpy as np

class HarmonicSphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        r = np.linalg.norm(x)
        return r**2 + 0.1 * np.sum(np.abs(x)) * np.exp(-r**2 / 10)

import numpy as np

class UniformPeriodicLattice:
    def __init__(self, dim=5):
        self.dim = dim
        self.frequency = 0.35  # ~7 oscillations in [-5, 5] range

    def f(self, x):
        n = len(x)

        # Primary term: uniform periodic grid across all dimensions
        # Creates identical basin sizes through consistent frequency
        primary_term = sum(np.cos(2 * np.pi * self.frequency * x[i])**2 
                         for i in range(n))

        # Secondary term: cross-dimensional coupling maintaining same frequency
        # Adds complexity while preserving basin size homogeneity
        cross_term = 0.15 * sum(np.cos(2 * np.pi * self.frequency * (x[i] + x[(i+1)%n]))**2 
                              for i in range(n))

        # Tertiary term: rotational coupling for isotropic behavior
        rotational_term = 0.1 * sum(np.cos(2 * np.pi * self.frequency * (x[i] - x[(i+1)%n]))**2 
                                  for i in range(n))

        return primary_term + cross_term + rotational_term
